/**
 * `09` §13.1 的 20 条固定问题 → 工具调用序列 + 字段级期望（**纯数据**，不含取数逻辑）。
 *
 * 这张表是 T3–T6 的判据：期望一律按**规格**写（§3.5 空原因字面值、§4.5 三处硬限制、
 * §13.1 的「必须出现的东西」），不按今天的实现写。今天兑现不了的地方就是红单。
 *
 * ## 路径语法（回放 runner 实现）
 *
 * - 默认取**最后一次**调用的 `工具结果`：`"空原因"`、`"数据.笔数"`、`"数据.0.合计"`。
 * - `"步N.…"` 取第 N 次调用（0 起）的结果：用在「一句话要同时看两三个查询」的题上
 *   （出处题要看关系引用的原文切片 + 明细行的材料定位；通话高峰要先翻行再抽验时长）。
 * - 参数里的占位串：`"@数据集.材料.话单"`、`"@结果.0.数据.0.id"`（只认本表出现过的两种）。
 *
 * ## 特殊期望值（`toEqual` 表达不了的两条规格）
 *
 * - `{ 非空: true }`：规格要求「非空」（如 §13.1 的「出处能翻到原文」），不钉具体内容——
 *   具体切多长是 T6 的设计决定，钉死会把 T6 的实现口径抢过来。
 * - `{ 含: "…" }`：规格要求 `缺口`「含」一句话（§4.5 第 2 条），数组里任一元素包含即可。
 *
 * ## 账号字面值
 *
 * 与 `dataset.ts` 的账号表逐字一致（计划「数据集」节是唯一权威）：
 * A=张三主账户、D=张三次账户、G=只注册无事实。
 */

export type 工具名 =
  | "search_materials"
  | "query_entities"
  | "query_relations"
  | "query_events"
  | "get_citation"
  | "query_rows"
  | "aggregate_money"
  | "find_crossings"

export type 断言项 = { 路径: string; 期望: unknown }

export interface 期望条 {
  组: "人" | "账户" | "时间线" | "空结果" | "其余"
  问题: string
  /** 默认主项目；「项目资金材料未翻译」必须打在副项目上。 */
  项目?: "主项目" | "待解析项目"
  调用: { 工具: 工具名; 参数: Record<string, unknown> }[]
  期望: 断言项[]
  /** = `调用.length`（编码序列的长度，不是模型侧的调用上限；模型侧见 §13.5）。 */
  最大调用数: number
}

/** 计划「数据集」节的时间一律按 Asia/Shanghai（UTC+8）解释（`case-time.ts` 同一判据）。 */
const 沪秒 = (文本: string): number => Date.parse(`${文本}+08:00`) / 1000

const 账号A = "6222021234567890123"
/** 张三次账户：只有 `持有` 关系，无明细、无转账 ⇒「确实没有交易」。 */
const 账号D = "6217000011112222333"
/** 只注册、无任何事实 ⇒「账户未在材料中出现」。 */
const 账号G = "6222021234567890888"

